function checkCsvShape(source) {
  const text = source.replace(/^\uFEFF/, "");
  let quoted = false,
    afterQuote = false,
    atStart = true;
  let width = 1,
    expectedWidth,
    separator;
  const endRow = () => {
    expectedWidth ??= width;
    if (width !== expectedWidth)
      throw Error("A CSV row has a different number of columns than the header.");
    width = 1;
    afterQuote = false;
    atStart = true;
  };
  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    if (quoted) {
      if (char === '"' && text[i + 1] === '"') i++;
      else if (char === '"') {
        quoted = false;
        afterQuote = true;
      }
      continue;
    }
    if (char === ",") {
      width++;
      atStart = true;
      afterQuote = false;
    } else if (char === "\r" || char === "\n") {
      const current = char === "\r" && text[i + 1] === "\n" ? char + text[++i] : char;
      separator ??= current;
      if (current !== separator) throw Error("Use one line ending throughout the CSV.");
      endRow();
    } else {
      if (afterQuote || (char === '"' && !atStart)) throw Error("Invalid quote in a CSV field.");
      quoted = char === '"';
      atStart = false;
    }
  }
  if (quoted) throw Error("Unclosed quote in the CSV.");
  if (!atStart || width > 1) endRow();
}

const item = $input.first(),
  file = item.binary?.file;
const types = [
  "text/csv",
  "application/csv",
  "application/vnd.ms-excel",
  "text/plain",
  "application/octet-stream",
];
if (
  !file ||
  Object.keys(item.binary).length !== 1 ||
  !/\.csv$/i.test(file.fileName ?? "") ||
  !types.includes(String(file.mimeType).split(";")[0].trim().toLowerCase())
)
  throw Error("Upload one CSV file in the multipart file field.");
const bytes = await helpers.getBinaryDataBuffer(0, "file");
if (!bytes.length || bytes.length > 1024 * 1024) throw Error("Upload a non-empty CSV up to 1 MiB.");
let text;
try {
  text = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
} catch {
  throw Error("Use a UTF-8 CSV file.");
}
checkCsvShape(text);
return [{ json: {}, binary: item.binary, pairedItem: { item: 0 } }];

function uploadedProfiles(rows, headers, key) {
  const first = rows[0];
  if (
    !Array.isArray(first) ||
    first.length > 100 ||
    first.some((x) => typeof x !== "string" || !x.trim())
  )
    throw Error("The CSV needs a non-empty header row.");
  const names = first.map((cell) => cell.replace(/^\uFEFF/, "").trim());
  if (new Set(names).size !== names.length || !names.includes("Email"))
    throw Error("The CSV needs one unique Email column and unique headers.");
  if (rows.length < 2 || rows.length > 1001)
    throw Error("Upload a CSV containing 1 to 1,000 profile rows.");
  const indexes = Object.fromEntries(
    headers.filter((h) => names.includes(h)).map((h) => [h, names.indexOf(h)]),
  );
  const mapped = new Map();
  for (const row of rows.slice(1)) {
    if (
      !Array.isArray(row) ||
      row.length !== first.length ||
      row.some((x) => typeof x !== "string")
    )
      throw Error("Profile row does not match the CSV header.");
    const profile = Object.fromEntries(Object.entries(indexes).map(([name, i]) => [name, row[i]]));
    profile.Email = profile.Email.trim();
    profile["Accepts Marketing"] ??= "";
    const email = key(profile.Email);
    if (mapped.has(email)) throw Error("The upload contains more than one row for an email.");
    mapped.set(email, profile);
  }
  return [...mapped.values()];
}

function customerEmail(email) {
  if (typeof email !== "string") throw Error("A required customer email is missing.");
  const key = email.trim().toLowerCase();
  if (
    !/^[^@\s,;<>\x00-\x1f]{1,64}@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+$/.test(key) ||
    key.length > 254
  ) {
    throw Error("A customer row has an invalid or missing email.");
  }
  return key;
}

