function customerConfig(settings) {
  const { spreadsheetId, profiles, customers } = settings;
  if (
    typeof spreadsheetId !== "string" ||
    !/^[A-Za-z0-9_-]{10,150}$/.test(spreadsheetId) ||
    spreadsheetId === "YOUR_SPREADSHEET_ID" ||
    [profiles, customers].some(
      (x) => typeof x !== "string" || !x.trim() || x.length > 100 || /[\r\n\x00-\x1f]/.test(x),
    ) ||
    profiles.trim().toLowerCase() === customers.trim().toLowerCase()
  )
    throw Error("Set one spreadsheet ID and two distinct tab names.");
  const range = (name, end) => "'" + name.replaceAll("'", "''") + "'!A:" + end;
  const root = "https://sheets.googleapis.com/v4/spreadsheets/" + spreadsheetId;
  const fields =
    "spreadsheetId,sheets(properties(sheetId,title,gridProperties(rowCount,columnCount)),data(startRow,startColumn,rowData(values(formattedValue,userEnteredValue)))";
  return {
    ...settings,
    readUrl:
      root +
      "?ranges=" +
      encodeURIComponent(range(profiles, "AI")) +
      "&ranges=" +
      encodeURIComponent(range(customers, "Q")) +
      "&includeGridData=true&fields=" +
      encodeURIComponent(fields),
    writeUrl: root + ":batchUpdate",
  };
}

const settings = {
  spreadsheetId: "YOUR_SPREADSHEET_ID",
  profiles: "Squarespace profiles",
  customers: "Shopify customers",
};
return [{ json: { ...$input.first().json, settings: customerConfig(settings) } }];

function planCustomerUpdates(reply, input, rawHeaders, shopHeaders, emailKey, transform) {
  const settings = input.settings;
  if (
    reply?.spreadsheetId !== settings.spreadsheetId ||
    !Array.isArray(reply.sheets) ||
    reply.sheets.length !== 2
  ) {
    throw Error("Sheets did not return the configured spreadsheet and its two tabs.");
  }
  function table(title, headers) {
    const sheet = reply.sheets.find((x) => x.properties?.title === title);
    const { sheetId, gridProperties } = sheet?.properties ?? {};
    const block = sheet?.data?.[0];
    if (
      !Number.isSafeInteger(sheetId) ||
      sheetId < 0 ||
      !Number.isSafeInteger(gridProperties?.rowCount) ||
      !Number.isSafeInteger(gridProperties?.columnCount) ||
      gridProperties.columnCount < headers.length ||
      sheet.data?.length !== 1 ||
      (block?.startRow ?? 0) !== 0 ||
      (block?.startColumn ?? 0) !== 0 ||
      !Array.isArray(block?.rowData) ||
      block.rowData.length > 2001 ||
      block.rowData.length > gridProperties.rowCount
    )
      throw Error("Check the configured sheet grid and its capacity.");
    const cell = (raw) => raw?.formattedValue ?? raw?.userEnteredValue?.stringValue ?? "";
    if (headers.some((label, i) => cell(block.rowData[0]?.values?.[i]) !== label))
      throw Error("The configured tab headers do not match the template.");
    const known = new Map();
    let next = 1;
    for (let i = 1; i < block.rowData.length; i++) {
      const values = headers.map((_, j) => cell(block.rowData[i]?.values?.[j]));
      if (values.every((x) => x === "")) continue;
      if (values.some((v) => typeof v !== "string"))
        throw Error("Sheets returned a non-text customer value.");
      const record = Object.fromEntries(headers.map((name, j) => [name, values[j]]));
      const key = emailKey(record.Email);
      if (known.has(key)) throw Error("A tab contains duplicate customer emails.");
      known.set(key, { row: i, record });
      next = i + 1;
    }
    return { sheetId, headers, known, next, rowLimit: gridProperties.rowCount };
  }
  const raw = table(settings.profiles, rawHeaders),
    target = table(settings.customers, shopHeaders);
  if (raw.sheetId === target.sheetId) throw Error("Select two distinct Sheets tabs.");
  const requests = [];
  const plan = (tab, key, patch) => {
    const old = tab.known.get(key);
    const row = old?.row ?? tab.next++;
    if (row >= tab.rowLimit || row > 2000)
      throw Error("Add enough empty grid rows and keep each tab at or below 2,000 profiles.");
    const indexes = tab.headers
      .map((h, i) => [h, i])
      .filter(([h]) => Object.hasOwn(patch, h) && patch[h] !== (old?.record?.[h] ?? ""));
    let startColumn,
      endColumn,
      cells = [];
    const flush = () => {
      if (!cells.length) return;
      requests.push({
        updateCells: {
          start: { sheetId: tab.sheetId, rowIndex: row, columnIndex: startColumn },
          rows: [{ values: cells }],
          fields: "userEnteredValue",
        },
      });
      cells = [];
    };
    for (const [h, i] of indexes) {
      if (cells.length && i !== endColumn) flush();
      if (!cells.length) startColumn = i;
      endColumn = i + 1;
      cells.push({ userEnteredValue: { stringValue: patch[h] } });
    }
    flush();
    return { ...old?.record, ...patch };
  };
  const incoming =
    input.mode === "upload" ? input.profiles : [...raw.known.values()].map((x) => x.record);
  for (const profile of incoming) {
    const key = emailKey(profile.Email);
    const complete = input.mode === "upload" ? plan(raw, key, profile) : profile;
    plan(target, key, transform(complete));
  }
  return {
    request: { requests, includeSpreadsheetInResponse: false },
    summary: { mode: input.mode, profiles: incoming.length },
    writeUrl: settings.writeUrl,
    spreadsheetId: settings.spreadsheetId,
    count: requests.length,
  };
}

