function shopifyCustomer(profile, countryOf, regionOf) {
  const read = (key) => profile[key] ?? "";
  const country = countryOf(read("Billing Country"));
  const region = regionOf(read("Billing Province/State"), country);
  const consent = /^(yes|true|1)$/i.test(read("Accepts Marketing").trim()) ? "yes" : "no";
  return {
    "First Name": read("First Name"),
    "Last Name": read("Last Name"),
    Email: read("Email"),
    "Accepts Email Marketing": consent,
    "Default Address Company": read("Billing Name"),
    "Default Address Address1": read("Billing Address 1"),
    "Default Address Address2": read("Billing Address 2"),
    "Default Address City": read("Billing City"),
    "Default Address Province Code": region,
    "Default Address Country Code": country,
    "Default Address Zip": read("Billing Zip"),
    "Default Address Phone": read("Billing Phone Number"),
    Phone: read("Billing Phone Number"),
    Tags: read("Last Order Date").trim() ? "n8n, squarespace, ground-control" : "n8n, squarespace",
  };
}

function shopifyCountry(value) {
  const text = value.trim();
  if (!text) return "";
  const countries =
    "AD AE AF AG AI AL AM AO AQ AR AS AT AU AW AX AZ BA BB BD BE BF BG BH BI BJ BL BM BN BO BQ BR BS BT BV BW BY BZ CA CC CD CF CG CH CI CK CL CM CN CO CR CU CV CW CX CY CZ DE DJ DK DM DO DZ EC EE EG EH ER ES ET FI FJ FK FM FO FR GA GB GD GE GF GG GH GI GL GM GN GP GQ GR GS GT GU GW GY HK HM HN HR HT HU ID IE IL IM IN IO IQ IR IS IT JE JM JO JP KE KG KH KI KM KN KP KR KW KY KZ LA LB LC LI LK LR LS LT LU LV LY MA MC MD ME MF MG MH MK ML MM MN MO MP MQ MR MS MT MU MV MW MX MY MZ NA NC NE NF NG NI NL NO NP NR NU NZ OM PA PE PF PG PH PK PL PM PN PR PS PT PW PY QA RE RO RS RU RW SA SB SC SD SE SG SH SI SJ SK SL SM SN SO SR SS ST SV SX SY SZ TC TD TF TG TH TJ TK TL TM TN TO TR TT TV TW TZ UA UG UM US UY UZ VA VC VE VG VI VN VU WF WS YE YT ZA ZM ZW".split(
      " ",
    );
  const upper = text.toUpperCase();
  if (countries.includes(upper)) return upper;
  const alias = {
    uk: "GB",
    "united states of america": "US",
    usa: "US",
    "south korea": "KR",
    "czech republic": "CZ",
  };
  const region = new Intl.DisplayNames(["en"], { type: "region", fallback: "none" });
  const match =
    alias[text.toLowerCase()] ??
    countries.find((code) => region.of(code)?.toLowerCase() === text.toLowerCase());
  if (!match)
    throw Error("A billing country is not a recognized English country or ISO alpha-2 code.");
  return match;
}

function shopifyRegion(value, country) {
  const text = value.trim();
  if (!text) return "";
  if (!country) throw Error("Set a billing country before specifying a billing region.");
  const maps = {
    US: "AL:Alabama|AK:Alaska|AZ:Arizona|AR:Arkansas|CA:California|CO:Colorado|CT:Connecticut|DE:Delaware|DC:District of Columbia|FL:Florida|GA:Georgia|HI:Hawaii|ID:Idaho|IL:Illinois|IN:Indiana|IA:Iowa|KS:Kansas|KY:Kentucky|LA:Louisiana|ME:Maine|MD:Maryland|MA:Massachusetts|MI:Michigan|MN:Minnesota|MS:Mississippi|MO:Missouri|MT:Montana|NE:Nebraska|NV:Nevada|NH:New Hampshire|NJ:New Jersey|NM:New Mexico|NY:New York|NC:North Carolina|ND:North Dakota|OH:Ohio|OK:Oklahoma|OR:Oregon|PA:Pennsylvania|RI:Rhode Island|SC:South Carolina|SD:South Dakota|TN:Tennessee|TX:Texas|UT:Utah|VT:Vermont|VA:Virginia|WA:Washington|WV:West Virginia|WI:Wisconsin|WY:Wyoming",
    CA: "AB:Alberta|BC:British Columbia|MB:Manitoba|NB:New Brunswick|NL:Newfoundland and Labrador|NT:Northwest Territories|NS:Nova Scotia|NU:Nunavut|ON:Ontario|PE:Prince Edward Island|QC:Quebec|SK:Saskatchewan|YT:Yukon",
    AU: "ACT:Australian Capital Territory|NSW:New South Wales|NT:Northern Territory|QLD:Queensland|SA:South Australia|TAS:Tasmania|VIC:Victoria|WA:Western Australia",
  };
  const code = text.toUpperCase().replace(new RegExp("^" + country + "-"), "");
  if (!maps[country] && /^[A-Z0-9]{1,3}$/.test(code)) return code;
  const normalize = (x) => x.normalize("NFD").replace(/\p{M}/gu, "").toLowerCase();
  const match = maps[country]
    ?.split("|")
    .map((x) => x.split(":"))
    .find(([id, name]) => id === code || normalize(name) === normalize(text));
  if (!match)
    throw Error("A billing province or state needs its documented Shopify subdivision code.");
  return match[0];
}

