function customerWriteReceipt(plan, response) {
  if (
    plan.count > 0 &&
    (response?.spreadsheetId !== plan.spreadsheetId ||
      !Array.isArray(response.replies) ||
      response.replies.length !== plan.count)
  )
    throw Error("Google Sheets did not confirm the batch. Inspect both tabs before retrying.");
  return { ...plan.summary, updatedRanges: plan.count, accepted: true };
}

const plan = $("Match customer rows by email").first().json;
